-- | Neural Network Dispatcher for Real-Time AC Power Flow
--
-- Provides fast (~1-5ms) inference for real-time P,Q dispatch decisions,
-- trained on samples generated by the IPOPT optimal power flow solver.
--
-- Key features:
--   * Outputs P,Q setpoints (not V,δ) — what inverters actually control
--   * MC Dropout for uncertainty quantification
--   * Physics-informed loss during training
--   * Persistent Python subprocess for low-latency inference
--
-- Architecture:
--
-- @
-- Input:                           Output:
-- ┌─────────────────────────┐      ┌─────────────────────────┐
-- │ hour                    │      │ P_set_1 ... P_set_N     │
-- │ P_max_1 ... P_max_N     │  ──▶ │ Q_set_1 ... Q_set_N     │
-- │ P_load_0 ... P_load_N   │      │ uncertainty             │
-- │ Q_load_0 ... Q_load_N   │      └─────────────────────────┘
-- └─────────────────────────┘
--
-- Hidden layers (with dropout kept at inference for MC Dropout):
--   Input → Dense(256) → ReLU → Dropout(0.1)
--        → Dense(256) → ReLU → Dropout(0.1)
--        → Dense(128) → ReLU → Dropout(0.05)
--        → Output
-- @

module Chopaan.AC.NeuralDispatch
  ( -- * Types
    DispatchNet(..)
  , DispatchResult(..)
  , InferenceServer(..)
    -- * Server Lifecycle
  , startInferenceServer
  , stopInferenceServer
  , withInferenceServer
    -- * Inference
  , dispatch
  , dispatchWithUncertainty
    -- * Validation
  , validateDispatch
  , ValidationResult(..)
  ) where

